# Toggles the person's hold. Responds with the sheet's people.
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
