import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

// retiredFrom is null unless the person is retired; once set, they count as retired whatever the date.
// While held, their OPEN claims count in no live total; their SETTLED ones still do.
export type Person = { id: number; name: string; grade: Grade; version: number; retiredFrom: string | null; held: boolean };

export const isRetired = (p: Person) => p.retiredFrom !== null;

export const peopleKey = (sheet: string) => ['people', sheet] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in the order they were added. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(peoplePath(sheet)),
  });
}

/** Whether retired people are listed: off until turned on, and kept in the URL so loading a sheet leaves it be. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, peoplePath } from './people';
import type { Person } from './people';

function HoldHeader() {
  return (
    <>
      <th>Hold</th>
      <th />
    </>
  );
}

// Whether the person is on hold, and the button that puts them on hold or takes them off it. While held,
// their OPEN claims count in no live total; their SETTLED ones still do.
function PersonHold({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const hold = useMutation({
    mutationFn: () => postJson<Person[]>(byUser(`${peoplePath(sheet)}/${person.id}/hold`, user), {}),
    onSuccess: (updated) => queryClient.setQueryData(peopleKey(sheet), updated),
  });
  const act = useSubmitOnce(hold);

  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        <button type="button" data-testid="person-hold-toggle" disabled={hold.isPending} onClick={() => act(undefined)}>
          {person.held ? 'Release' : 'Hold'}
        </button>
        {hold.isError && (
          <span data-testid="person-error" role="alert">
            {' '}That hold was refused.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 40, Component: HoldHeader }),
  PersonColumns.fill({ order: 40, Component: PersonHold }),
];
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/**
 * Extra columns of the people table. A column fills both regions: its header cell in
 * PersonColumnHeaders and, per person, its <td> in PersonColumns (inside `person-row-<id>`).
 */
export const PersonColumnHeaders = defineSlot<{ sheet: string; user: string }>('person.column-headers');
export const PersonColumns = defineSlot<{ sheet: string; user: string; person: Person }>('person.columns');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
